{
  "candidates": [
    {
      "explanation": "Moderate demand surge: increase orders at all nodes to build pipeline, but avoid over-ordering at node2 where inventory is high. Node0 backlog and low inventory require immediate boost; node1 has sufficient inventory but should prepare for increased downstream demand; node2 has ample inventory and pipeline, so only small increase.",
      "rules": [
        {
          "when": "agent == 0",
          "delta": "min(6, max(0, (recent - baseline) * 2 + backlog * 0.5))"
        },
        {
          "when": "agent == 1",
          "delta": "min(4, max(0, (recent - baseline) * 1.5))"
        },
        {
          "when": "agent == 2",
          "delta": "min(2, max(0, (recent - baseline) * 0.5))"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand to prevent overstock, but increase when inventory is low or backlog exists. Node0 has high pipeline but also backlog, so slight increase; node1 pipeline is high, so reduce; node2 pipeline moderate but inventory high, so reduce.",
      "rules": [
        {
          "when": "agent == 0",
          "delta": "min(4, max(-2, backlog * 0.5 - (pipeline - recent * 4) * 0.1))"
        },
        {
          "when": "agent == 1",
          "delta": "min(2, max(-4, (recent - baseline) * 1.5 - (pipeline - recent * 4) * 0.2))"
        },
        {
          "when": "agent == 2",
          "delta": "min(2, max(-4, (recent - baseline) * 0.5 - (pipeline - recent * 4) * 0.2))"
        }
      ]
    },
    {
      "explanation": "Coordinated response: node0 increases to clear backlog and meet demand; node1 increases moderately to support node0; node2 reduces to avoid excess inventory since its inventory is high and pipeline sufficient. Uses growth to scale increases.",
      "rules": [
        {
          "when": "agent == 0",
          "delta": "min(6, max(0, backlog * 0.8 + (growth - 1) * 10))"
        },
        {
          "when": "agent == 1",
          "delta": "min(4, max(0, (growth - 1) * 8))"
        },
        {
          "when": "agent == 2",
          "delta": "min(0, max(-4, (growth - 1) * 5 - inventory * 0.05))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Moderate demand-responsive increase at all nodes to reduce backlog, with pipeline-aware caps to avoid overordering.",
      "rules": [
        {
          "when": "agent==0 and backlog>0 and growth>1.2",
          "delta": "min(4, max(0, (recent-baseline)*0.5))"
        },
        {
          "when": "agent==1 and backlog>0 and growth>1.2",
          "delta": "min(4, max(0, (recent-baseline)*0.5))"
        },
        {
          "when": "agent==2 and inventory<10 and growth>1.2",
          "delta": "min(4, max(0, (recent-baseline)*0.5))"
        }
      ]
    },
    {
      "explanation": "Stronger increase at node0 to clear backlog and at node1 to prevent stockout, but node2 only if inventory low.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, max(0, backlog*0.8 + (recent-baseline)*0.3))"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(6, max(0, backlog*0.8 + (recent-baseline)*0.3))"
        },
        {
          "when": "agent==2 and inventory<5",
          "delta": "min(6, max(0, (recent-baseline)*0.5))"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, increase when backlog and pipeline low.",
      "rules": [
        {
          "when": "agent==0 and pipeline>recent*4 and backlog==0",
          "delta": "-2"
        },
        {
          "when": "agent==0 and backlog>0 and pipeline<recent*3",
          "delta": "min(5, max(0, backlog*0.5 + (recent-baseline)*0.4))"
        },
        {
          "when": "agent==1 and pipeline>recent*4 and backlog==0",
          "delta": "-2"
        },
        {
          "when": "agent==1 and backlog>0 and pipeline<recent*3",
          "delta": "min(5, max(0, backlog*0.5 + (recent-baseline)*0.4))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Refinement of best candidate (llm_r0_0) with pipeline-aware relaxation to reduce upstream backlog while maintaining downstream service. Node0: increase order to clear backlog and build pipeline, but moderate if pipeline already high. Node1: increase to support node0's demand, but reduce if pipeline is excessive. Node2: small increase to avoid starving node1, but reduce if pipeline is very high. All deltas clipped to [-6,6].",
      "rules": [
        {
          "when": "agent == 0",
          "delta": "min(6, max(-2, backlog * 0.6 + (recent - baseline) * 1.5 - max(0, pipeline - recent * 4) * 0.1))"
        },
        {
          "when": "agent == 1",
          "delta": "min(4, max(-3, (recent - baseline) * 1.2 + backlog * 0.2 - max(0, pipeline - recent * 4) * 0.15))"
        },
        {
          "when": "agent == 2",
          "delta": "min(2, max(-4, (recent - baseline) * 0.5 - max(0, pipeline - recent * 4) * 0.2))"
        }
      ]
    }
  ]
}

