      "rules": [
        {
          "when": "agent==0 and backlog>0 and pipeline<recent*5",
          "delta": "min(3, max(0, (recent-baseline)*0.4 + backlog*0.05))"
        },
        {
          "when": "agent==0 and backlog>0 and pipeline>=recent*5",
          "delta": "0"
        },
        {
          "when": "agent==1",
          "delta": "0"
        },
        {
          "when": "agent==2",
          "delta": "0"
        }
      ]
    }
  ]
